   "question": "面对复杂严峻的形势，以习近平同志为核心的党中央深刻把握世界大势和发展规律，科学分析我国发展面临机遇和挑战的新变化，着眼我国经济中长期发展，作出加快形成新发展格局的重大战略部署。关于我国新发展格局，下列理解正确的有几项？\n①努力把满足国内需求作为发展的出发点和落脚点\n②充分发挥国内超大规模市场优势\n③逐步形成以国内大循环为主体、国内国际双循环相互促进的格局\n④深化收入分配改革是形成以国内大循环为主体的关键",
