   "question": "习总书记强调，要大兴调查研究之风，深入了解群众需求，切实解决广大老百姓关心关切的利益问题，不断提高人民群众的获得感、幸福感、安全感，关于调查研究正确的有几项？\n①调查研究是我们党的传家宝，是做好各项工作的基本功\n②要大兴务实之风，抓好调查研究，在察实情、出实招、求实效上下功夫\n③检验调查研究成效，要看是否摸清社情民意、是否解决实际问题\n④调查研究是了解情况的主要渠道，不能通过二手材料了解情况",
