   "analysis": "本题考查政治常识。\n①②③正确，④错误，2023年7月17日至18日，全国生态环境保护大会在北京召开。习近平指出，要健全美丽中国建设保障体系。统筹各领域资源，汇聚各方面力量，打好法治、市场、科技、政策“组合拳”。要强化法治保障，统筹推进生态环境、资源能源等领域相关法律制修订，实施最严格的地上地下、陆海统筹、区域联动的生态环境治理制度，全面实行排污许可制，完善自然资源资产管理制度体系，健全国土空间用途管制制度。要完善绿色低碳发展经济政策，强化财政支持、税收政策支持、金融支持、价格政策支持。要推动有效市场和有为政府更好结合，将碳排放权、用能权、用水权、排污权等资源环境要素一体纳入要素市场化配置改革总盘子，支持出让、转让、抵押、入股等市场交易行为，加快构建环保信用监管体系，规范环境治理市场，促进环保产业和环境服务业健康发展。\n故正确答案为D。",
   "exam": "guokao",
   "year": 2024
