   "question": "习近平总书记指出，农业强国是社会主义现代化强国的根基，满足人民美好生活需要、实现高质量发展、夯实国家安全基础，都离不开农业发展。下列关于建设农业强国的表述正确的是：\n①农业科技创新要以农业关键核心技术攻关为引领，以促进大规模经营为导向\n②要坚持把增加农民收入作为“三农”工作的中心任务\n③要一体推进农业现代化和农村现代化，实现乡村由表及里、形神兼备的全面提升\n④扩大耕地面积是建设农业强国的首要任务",
