   "question": "习近平总书记强调，粮食安全是“国之大者”。下列保障粮食安全的举措正确的有几项？\n①全面落实粮食安全党政同责，坚持稳面积、增单产两手发力\n②树立大农业观、大食物观，农林牧渔并举，构建多元化食物供给体系\n③加大高标准农田建设投入和管护力度，确保耕地数量有保障、质量有提升\n④扩大粮食领域高水平对外开放，逐步加大国外优质种业资源和海外粮食产品在我国市场的占有率\n⑤强化科技和改革双轮驱动，加大核心技术攻关力度",
