   "source": "2016年国家公务员录用考试《行测》题（地市级） · 第4题",
   "question": "下列说法不符合我国法律规定的是：",
   "options": [
    "A. 甲带侄子外出游玩，遇地震，甲无需为侄子在地震中所受损害承担责任",
    "B. 甲用拳头殴打乙，乙将甲推倒后持刀将其扎死，乙无需为甲的死亡承担责任",
    "C. 甲、乙发生口角，对骂过程中甲欲讹诈乙而故意倒地，乙无需为甲因倒地所受伤害承担责任",
    "D. 甲、乙因言语不和而厮打一起，丙撞见后趁机殴打与其素来不和的甲，乙无需为丙殴打甲所造成的损害承担责任"
   ],
   "answer": "B",
   "analysis": "本题考查法律常识。\nA项正确，“遇地震”属于“不可抗力”，根据《刑法》第十六条规定，行为在客观上虽然造成了损害结果，但是不是出于故意或者过失，而是由于不能抗拒或者不能预见的原因所引起的，不是犯罪。根据《民法典》第一百八十条规定：“因不可抗力不能履行民事义务的，不承担民事责任。法律另有规定的，依照其规定。不可抗力是不能预见、不能避免且不能克服的客观情况。”\nB项错误，乙将甲推倒属于正当防卫，当甲被推倒证明不法侵害人已经被制伏，因而此时乙再持刀将其扎死不属于防卫，构成故意杀人罪，需要承担刑事责任。\nC项正确，甲欲讹诈乙故意倒地，即“甲倒地”是自己造成的，与乙没有因果关系，乙无需担责。\nD项正确，丙殴打甲的行为与乙没有关联，乙无需担责。\n本题为选非题，故正确答案为B。",
