   "source": "2019年国家公务员录用考试《行测》题（副省级） · 第15题",
   "question": "摄影师在野外环境中最不可能拍摄到的是：",
   "options": [
    "A. 在云南丽江拍摄成片的针叶林",
    "B. 在青海拍摄成群的藏羚羊",
    "C. 在阿拉伯半岛拍摄海豹",
    "D. 在冰岛拍摄火山喷发"
   ],
   "answer": "C",
   "analysis": "本题考查地理国情。\nA项正确，针叶林主要由云杉、冷杉、落叶松和松树等一些耐寒树种组成，主要分布于寒温带及中、低纬度亚高山地区的常绿或落叶针叶林。丽江市属低纬亚高山地区，此处分布有丽江云杉等植被，组成单纯林或与其他针叶树组成混交林。因此有可能在丽江拍摄成片的针叶林。\nB项正确，藏羚羊栖息于海拔3700-5500米的高山草原、草甸和高寒荒漠地带，为中国一级保护动物，主要分布于中国以羌塘为中心的青藏高原地区（青海、西藏、新疆）。因此有可能在青海拍摄成群的藏羚羊。\nC项错误，海豹主要生活在寒温带海洋中。南极海豹数量最多，其次是北冰洋、北大西洋、北太平洋等地。而阿拉伯半岛常年受副高及信风带控制，非常干燥，几乎整个半岛都是热带沙漠气候区并有面积较大的无流区。因此最不可能在阿拉伯半岛拍摄海豹。\nD项正确，冰岛型火山喷发，裂隙式喷发。因现仅能在冰岛观察到这种火山喷发，故叫冰岛型火山喷发。其特征是大量喷出易流动的玄武岩质熔岩，形成表面较平坦的熔岩台地。因此有可能在冰岛拍摄火山喷发。\n本题为选非题，故正确答案为C。",
   "exam": "guokao",
   "year": 2019
