   "analysis": "本题考查法律常识。\n《环境保护法》第五十八条规定：“对污染环境、破坏生态，损害社会公共利益的行为，符合下列条件的社会组织可以向人民法院提起诉讼：（一）依法在设区的市级以上人民政府民政部门登记；（二）专门从事环境保护公益活动连续五年以上且无违法记录。符合前款规定的社会组织向人民法院提起诉讼，人民法院应当依法受理。提起诉讼的社会组织不得通过诉讼牟取经济利益。”根据上述规定，无违法记录且符合年限要求的主体必须是依法在设区的市级以上人民政府民政部门登记的社会组织可以起诉。\n故正确答案为B。",
