   "source": "2021年国家公务员录用考试《行测》题（副省级） · 第11题",
   "question": "关于探测设备，下列说法错误的是：",
   "options": [
    "A. 热像仪可以在黑夜之中使用",
    "B. 声呐主要用于在陆地上及空中探测距离",
    "C. 雷达测距利用了无线电波沿直线传播的原理",
    "D. 地下金属探测仪器利用了电磁感应原理"
   ],
   "answer": "B",
   "analysis": "本题考查科技常识。\nA项正确，自然界中的一切物体都在不停地向外辐射红外线，热像仪利用这个原理，将物体辐射出的红外线的功率信号转换为电信号，经过处理，从而得到物体的热像图。因此，热像仪成像不依靠可见光，可以在黑夜中使用。\nB项错误，声呐是利用水中声波对水下目标进行距离探测、定位和通信的电子设备。由于电磁波在水中衰减大、传播距离短，雷达无法有效探测，而声波在水中衰减小，传播距离远，因此声呐就成为水下探测、定位和联系的重要工具，而在陆地上及空中进行探测主要使用雷达。\nC项正确，雷达是利用电磁波探测目标的电子设备。其原理为：距离img/formula-66bd44bcd558ab0a.webp，式中img/formula-8c971278e4698048.webp为雷达发出与接收电磁波的时间间隔，img/formula-f3a2e3e59d24c286.webp为电磁波传播速度。因此可知，雷达测距正是利用了电磁波沿直线传播的原理。\nD项正确，多数金属探测器利用电磁感应的原理，利用有交流电通过的线圈，产生迅速变化的磁场，这个磁场在金属物体内部能产生涡电流，涡电流又会产生磁场，反过来影响原来的磁场，引发探测器发出鸣声。\n本题为选非题，故正确答案为B。\nimg/17614135f78533b.webp",
   "exam": "guokao",
   "year": 2021
