   "source": "2021年国家公务员录用考试《行测》题（副省级） · 第12题",
   "question": "很多伟大科学家的墓志铭简练而富有诗意，是了解其一生成就的窗口。下列墓志铭与科学家对应错误的是：",
   "options": [
    "A. 我曾测量天空，现在测量幽冥。灵魂飞向天国，肉体安息土中——爱因斯坦",
    "B. 他把世界翻了一个个儿，虽然并不完全——达尔文",
    "C. 他从苍天处取得闪电，从暴君处取得民权——富兰克林",
    "D. 他失明了，因为自然界已经没有剩下什么他没有看见过的东西了——伽利略"
   ],
   "answer": "A",
   "analysis": "本题考查人文常识。\nA项错误，德国天文学家、数学家开普勒发现了行星运动的三大定律，分别是轨道定律、面积定律和周期定律。他为自己撰写的墓志铭是：“我曾测量天空，现在测量幽冥。灵魂飞向天国，肉体安息土中。”\nB项正确，英国科学家达尔文提出了生物进化论，他的墓志铭是：“他把世界翻了一个个儿，虽然并不完全。”\nC项正确，美国政治家、物理学家富兰克林发明了避雷针，他曾在雷电交加的情况下，利用风筝将大气电收集到莱顿瓶中，使其充电，由此证明了他所提出的“闪电和静电的同一性”的设想。法国经济学家杜尔哥评价富兰克林：“他从苍天处取得闪电，从暴君处取得民权。”\nD项正确，意大利天文学家伽利略研究了速度和加速度、重力和自由落体等理论，发明了温度计，并使用用于天体科学观测的望远镜。晚年的伽利略失明，后人在其墓志铭写道：“他失明了，因为自然界已经没有剩下什么他没有看见过的东西了。”\n本题为选非题，故正确答案为A。",
   "exam": "guokao",
