   "question": "关于我国近年来取得的重大科技成就，下列说法错误的是：",
   "options": [
    "A. “郭守敬望远镜”开创大规模光谱巡天，其光谱获取率全球最高",
    "B. “深海一号”在马里亚纳海沟成功坐底，创造了中国载人深潜纪录",
    "C. 中国散裂中子源就像“超级显微镜”，可探测物质微观结构",
    "D. “天问一号”任务在我国航天发展史上首次实现地外行星软着陆"
   ],
   "answer": "B",
   "analysis": "本题考查科技常识。\nA项正确，郭守敬望远镜（LAMOST）是一架由我国科学家自主创新设计、在技术上极具挑战性的大视场兼备大口径的新型光学天文望远镜，即“王-苏反射施密特望远镜”。作为国家重大科技基础设施之一，LAMOST在国际上首先发展了在一块镜面上同时实现几十块薄镜面的拼接和曲面形状的连续变化的主动光学技术，以及新的数千根光纤的快速定位技术，从而成为全球光学天文望远镜的一个里程碑。LAMOST在科学上开创了大规模的光谱巡天，成为目前世界上光谱获取率最高的望远镜，具有“光谱之王”的美誉。\nB项错误，2020年11月10日，我国自主研发的“奋斗者”号载人潜水器，在马里亚纳海沟，成功坐底深度10909米，再创我国载人深潜的新纪录。“深海一号”有两种含义，（1）“深海一号”是中国首艘载人潜水器支持母船，2017年9月16日在武汉开工建造；（2）“深海一号”是由我国自主研发建造的全球首座10万吨级深水半潜式生产储油平台。2021年6月25日，该平台正式投产，标志着中国从装备技术到勘探开发能力全面实现从300米到1500米超深水的跨越。\nC项正确，中国散裂中子源位于中国广东省东莞市境内，是中国国家“十一五”期间重点建设的十二大科学装置之首。中国散裂中子源可以探测微观物质结构，如散裂中子源优异的脉冲时间特性和高通量的超热中子有利于研究有机高分子体系中磁、热、电、光等物性与微观结构的关系等。\nD项正确，天问一号任务成功是中国航天事业自主创新，跨越发展的标志性成就。在中国航天发展史上，天问一号任务实现了6个首次，一是首次实现地火转移轨道探测器发射；二是首次实现行星际飞行；三是首次实现地外行星软着陆；四是首次实现地外行星表面巡视探测；五是首次实现4亿公里距离的测控通信；六是首次获取第一手的火星科学数据。\n本题为选非题，故正确答案为B。",
