   "question": "下列与宏观经济有关的说法，错误的是（    ）。",
   "options": [
    "A. 利率变化与资金供求关系有关",
    "B. 央行逆回购会减少市场流动性",
    "C. 国际收支顺差会给本币带来升值压力",
    "D. 提高贷款利率可用于控制通货膨胀"
   ],
   "answer": "B",
   "analysis": "本题考查经济常识。\nA项正确，资金供求状况的变化会影响利率。在资金市场上，资金供给超过对资本的需求时，利率便会下跌；反之，对资金的需求超过资金的供给，利率就会上升。\nB项错误，央行逆回购是指中国人民银行向一级交易商购买有价证券，并约定在未来特定日期将有价证券卖还给一级交易商的交易行为。其目的主要是向市场释放流动性，同时可以获得回购的利息收入。\nC项正确，国际收支顺差亦称“国际收支盈余”。在一定时期内（通常为一年），各个国家之间对外经济往来的收入总额大于支出总额的差额，即为顺差。国际收支顺差会使得国内外汇市场上的外币供给大于外币需求，进而产生外币贬值的预期和本币升值的预期。\nD项正确，通货膨胀一般指在纸币流通条件下，因货币供给大于货币实际需求，也即现实购买力大于产出供给，导致货币贬值而引起的一段时间内物价持续而普遍的上涨现象。提高贷款利率会增加贷款成本，降低市场上的贷款积极性，减少流通中的货币，从而有利于抑制通货膨胀。\n本题为选非题，故正确答案为B。",
