   "source": "2025年国家公务员录用考试《行测》题（副省级） · 第5题",
   "question": "下列物理学家与其提出的著名观点对应错误的是：",
   "options": [
    "A. 麦克斯韦：能量的交换不是连续的，而是以最小的不可分割的单元进行，这些单元被称为“量子”",
    "B. 安培：在原子、分子等物质微粒的内部，存在着一种环形电流-分子电流、使每个微粒成为微小的磁体",
    "C. 牛顿：任何两个物体之间都存在引力，这种力的大小与它们质量的乘积成正比，与它们之间的距离的平方成反比",
    "D. 伽利略：物体的运动并不需要力来维持，运动的物体之所以会停下来，是因为受到了阻力"
   ],
   "answer": "A",
   "analysis": "本题考查科技常识。\nA项错误，量子是现代物理的重要概念，即一个物理量如果存在最小的不可分割的基本单位，则这个物理量是量子化的，并把最小单位称为量子。该概念最早是由德国物理学家M·普朗克在1900年提出的。他假设黑体辐射中的辐射能量是不连续的，只能取能量基本单位的整数倍，从而很好地解释了黑体辐射的实验现象。麦克斯韦的主要贡献包括预言了电磁波的存在，建立了麦克斯韦方程组。\nB项正确，分子电流假说是安培提出的电磁学理论，他认为在原子、分子等物质微粒的内部，存在着一种环形电流——分子电流，使每个微粒成为微小的磁体，分子的两侧相当于两个磁极。通常情况下磁体分子的分子电流取向是杂乱无章的，它们产生的磁场互相抵消，对外不显磁性。当外界磁场作用后，分子电流的取向大致相同，分子间相邻的电流作用抵消，而表面部分未抵消，它们的效果显示出宏观磁性。\nC项正确，万有引力定律是艾萨克·牛顿于1687年在《自然哲学的数学原理》上所发表的一种自然规律，表述如下：任何两个质点都存在通过其连心线方向上的相互吸引的力。该引力大小与它们质量的乘积成正比，与它们之间的距离的平方成反比，与两物体的化学组成和其间介质种类无关。\nD项正确，物体的运动并不需要力来维持，运动的物体之所以会停下来，是因为受到了阻力。这一观点首先由伽利略通过实验分析得出的。伽利略通过斜面实验结合推理，证明了力不是维持物体运动的原因，而是改变物体运动状态的原因。\n本题为选非题，故正确答案为A。",
