   "analysis": "本题考查法律常识。\nA项正确，根据《中华人民共和国刑事诉讼法》第六十二条第一款规定：“凡是知道案件情况的人，都有作证的义务。”第一百九十三条规定：“经人民法院通知，证人没有正当理由不出庭作证的，人民法院可以强制其到庭，但是被告人的配偶、父母、子女除外。证人没有正当理由拒绝出庭或者出庭后拒绝作证的，予以训诫，情节严重的，经院长批准，处以十日以下的拘留。被处罚人对拘留决定不服的，可以向上一级人民法院申请复议。复议期间不停止执行。”题中，若乙为甲盗窃案的证人，由于甲乙系夫妻关系，乙有权拒绝出庭作证。\nB项错误，根据《中华人民共和国刑法》第三百一十条第一款规定：“明知是犯罪的人而为其提供隐藏处所、财物，帮助其逃匿或者作假证明包庇的，处三年以下有期徒刑、拘役或者管制；情节严重的，处三年以上十年以下有期徒刑。”题中，乙帮助甲逃匿，构成窝藏、包庇罪。\nC项错误，根据《中华人民共和国刑法》第六十七条第一款规定：“犯罪以后自动投案，如实供述自己的罪行的，是自首。对于自首的犯罪分子，可以从轻或者减轻处罚。其中，犯罪较轻的，可以免除处罚。”《最高人民法院关于处理自首和立功具体应用法律若干问题的解释》第一条规定：“······并非出于犯罪嫌疑人主动，而是经亲友规劝、陪同投案的；公安机关通知犯罪嫌疑人的亲友，或者亲友主动报案后，将犯罪嫌疑人送去投案的，也应当视为自动投案······”题中，乙陪同甲至公安机关投案，甲构成自首。\nD项错误，根据《中华人民共和国刑事诉讼法》第二百二十七条第一款规定：“被告人、自诉人和他们的法定代理人，不服地方各级人民法院第一审的判决、裁定，有权用书状或者口头向上一级人民法院上诉。被告人的辩护人和近亲属，经被告人同意，可以提出上诉。”题中，乙作为甲的近亲属，经甲同意后才能提出上诉。\n故正确答案为A。",
