   "analysis": "本题考查法律常识。\nA项正确，根据《中华人民共和国增值税法》第三条第一款规定：“在中华人民共和国境内（以下简称境内）销售货物、服务、无形资产、不动产（以下称应税交易），以及进口货物的单位和个人（包括个体工商户），为增值税的纳税人，应当依照本法规定缴纳增值税。”选项中，我国境内的半导体公司销售半导体产品，属于增值税征税范围，应征收增值税，因此，符合我国税收制度。\nB项错误，根据《中华人民共和国资源税法》第一条规定：“在中华人民共和国领域和中华人民共和国管辖的其他海域开发应税资源的单位和个人，为资源税的纳税人，应当依照本法规定缴纳资源税。应税资源的具体范围，由本法所附《资源税税目税率表》（以下称《税目税率表》）确定。”《资源税税目税率表》载明的应税资源的具体范围包括能源矿产、金属矿产、非金属矿产、水气矿产、盐。选项中，未做废弃物无害化处理的养殖场不属于开发应税资源的单位，不应对其征收资源税，因此，不符合我国税收制度。\nC项正确，根据《中华人民共和国消费税暂行条例》第一条规定：“在中华人民共和国境内生产、委托加工和进口本条例规定的消费品的单位和个人，以及国务院确定的销售本条例规定的消费品的其他单位和个人，为消费税的纳税人，应当依照本条例缴纳消费税。”第二条第一款规定：“消费税的税目、税率，依照本条例所附的《消费税税目税率表》执行。”《消费税税目税率表》载明税目“三、化妆品”的税率为“30%”。选项中，某进口高档化妆品公司进口本条例规定的消费品化妆品，属于消费税的纳税人，应对其征收消费税，因此，符合我国税收制度。\nD项正确，根据《中华人民共和国个人所得税法》第一条规定：“在中国境内有住所，或者无住所而一个纳税年度内在中国境内居住累计满一百八十三天的个人，为居民个人。居民个人从中国境内和境外取得的所得，依照本法规定缴纳个人所得税。在中国境内无住所又不居住，或者无住所而一个纳税年度内在中国境内居住累计不满一百八十三天的个人，为非居民个人。非居民个人从中国境内取得的所得，依照本法规定缴纳个人所得税。”选项中，该外籍居民在我国境内的外资企业工作多年，可认定其在中国境内居住累计满一百八十三天，符合“居民个人”的认定标准，应缴纳个人所得税，因此，符合我国税收制度。\n本题为选非题，故正确答案为B。",
