   "question": "“体重管理年”三年行动旨在引导全社会养成重视体重、科学饮食与锻炼的习惯，科学减重，健康生活。关于肥胖对健康的影响，下列说法错误的是：",
   "options": [
    "A. 肥胖容易引发胰岛素抵抗，增加患2型糖尿病风险",
    "B. 内脏脂肪组织分泌的炎症因子与动脉粥样硬化发展相关",
    "C. 肥胖者的排尿次数多，会导致血尿酸水平远低于正常人",
    "D. 肥胖引起的气道狭窄可能诱发阻塞性睡眠呼吸暂停"
   ],
   "answer": "C",
   "analysis": "本题考查科技常识。\nA项正确，肥胖是2型糖尿病的核心危险因素之一。当人体内脂肪（尤其是内脏脂肪）过量堆积时，会引发胰岛素抵抗——脂肪细胞会分泌多种物质干扰胰岛素的作用，导致人体需要分泌更多胰岛素才能控制血糖，长期超负荷会损伤胰岛img/formula-2cef1fcdc275c923.webp细胞功能，最终增加2型糖尿病的发病风险。\nB项正确，内脏脂肪并非单纯的“储能组织”，还具有内分泌功能。肥胖者内脏脂肪组织会大量分泌炎症因子（如img/formula-2d1880034395c34b.webp、IL-6等），这些炎症因子会损伤血管内皮细胞，促进血小板聚集、脂质沉积和动脉粥样硬化斑块形成，进而增加冠心病、脑梗死等心血管疾病的发生风险。\nC项错误，肥胖者的血尿酸水平通常高于正常人，而非“远低于”。一方面，肥胖者胰岛素抵抗会影响肾脏对尿酸的排泄功能，导致尿酸在体内蓄积；另一方面，脂肪组织代谢过程中会产生更多嘌呤，嘌呤分解的终产物即为尿酸，双重作用下肥胖者高尿酸血症的发病率显著升高。此外，排尿次数多与血尿酸水平无直接关联（排尿次数可能受饮水、代谢率等影响）。\nD项正确，肥胖者颈部、胸部脂肪大量堆积时，会压迫气道，导致气道狭窄、通气阻力增加；同时，脂肪组织对呼吸肌的负担会降低呼吸调节功能，夜间睡眠时容易出现上气道塌陷，引发阻塞性睡眠呼吸暂停（表现为打鼾、呼吸暂停、白天嗜睡等）。\n本题为选非题，故正确答案为C。",
