    "B. 禁止在长江流域开放水域养殖外来物种或者其他非本地物种",
    "C. 青、草、鲢、鳙四大家鱼会在长江和其附属湖泊之间洄游",
    "D. 在禁渔期内使用炸鱼、电鱼等方式捕捞，涉嫌刑事犯罪"
