   "analysis": "本题考查人文常识。\nA项错误，斗拱是中国传统木构建筑中特有的承重构件，能有效减少梁柱交接处的剪力。斗拱通过层层叠压的斗、拱、翘等部件，可以将梁架传递下来的竖向荷载分散。同时，斗拱的榫卯连接具有一定的弹性和转动空间，在荷载作用下可产生微小变形，吸收部分剪力能量，避免节点因剪力集中而开裂或损坏。飞檐是中国传统木构建筑中屋顶檐部向上翘起的特殊构造，主要具备排水、遮阳等功能。\nB项错误，台基是高出地面的建筑物底座，一大功能是防潮隔湿：高于室外地坪的基身，其主要部分是用多层夯土或夯土层与碎砖瓦石块层交互重叠、夯筑而成，这种做法可以有效地阻止地下水分的上升。防火功能主要通过其他建筑构件，如防火墙等实现。\nC项错误，藻井是天花向上凹进为穹窿状的部分，在历史演进中逐渐从实用性建筑构件转变为装饰性建筑构件，核心为装饰功能。且藻井的使用有着严格的等级规制，是传统礼制文化在建筑中的体现。窗户是建筑中最基本的通风和采光构件。\nD项正确，榫卯是在两个木构件上所采用的一种凹凸结合的连接方式。榫卯结构允许节点处的微小位移和变形，能有效耗散地震能量、缓冲地震冲击，从而大幅提升木构建筑的整体抗震性能。\n故正确答案为D。",
